'use client';

import { useState } from 'react';
import { Upload, X, Loader2 } from 'lucide-react';
import { uploadFile } from '@/lib/api';

interface FileUploadModalProps {
  isOpen: boolean;
  onClose: () => void;
  currentUserId: string;
  onSuccess: () => void;
}

export default function FileUploadModal({ isOpen, onClose, currentUserId, onSuccess }: FileUploadModalProps) {
  const [file, setFile] = useState<File | null>(null);
  const [loading, setLoading] = useState(false);

  if (!isOpen) return null;

  const handleUpload = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!file) return;

    try {
      setLoading(true);
      await uploadFile(file, currentUserId);
      setLoading(false);
      setFile(null);
      onSuccess();
      onClose();
    } catch (error) {
      console.error('File upload failed:', error);
      setLoading(false);
    }
  };

  return (
    <div className="fixed inset-0 bg-slate-900/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
      <div className="bg-white rounded-2xl max-w-md w-full p-6 shadow-xl border border-slate-100 animate-in fade-in zoom-in duration-200">
        
        <div className="flex items-center justify-between mb-4">
          <div className="flex items-center space-x-2 text-indigo-600">
            <Upload className="w-5 h-5" />
            <h3 className="text-base font-bold text-slate-900">Import Document File</h3>
          </div>
          <button onClick={onClose} className="text-slate-400 hover:text-slate-600 p-1 rounded-lg">
            <X className="w-5 h-5" />
          </button>
        </div>

        <p className="text-xs text-slate-500 mb-4">
          Upload a <span className="font-semibold text-slate-700">.txt</span> or <span className="font-semibold text-slate-700">.md</span> file. The content will be automatically converted into a new editable document.
        </p>

        <form onSubmit={handleUpload} className="space-y-4">
          <div className="border-2 border-dashed border-slate-200 rounded-xl p-6 text-center hover:border-indigo-400 transition-colors bg-slate-50">
            <input
              type="file"
              accept=".txt,.md"
              onChange={(e) => setFile(e.target.files?.[0] || null)}
              className="w-full text-xs text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-xl file:border-0 file:text-xs file:font-semibold file:bg-indigo-50 file:text-indigo-700 hover:file:bg-indigo-100 cursor-pointer"
            />
            {file && (
              <p className="mt-2 text-xs font-semibold text-indigo-600">Selected: {file.name}</p>
            )}
          </div>

          <div className="flex justify-end space-x-3 pt-2">
            <button
              type="button"
              onClick={onClose}
              className="px-4 py-2 text-xs font-semibold text-slate-600 hover:bg-slate-100 rounded-xl transition-colors"
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={!file || loading}
              className="px-4 py-2 text-xs font-semibold bg-indigo-600 text-white rounded-xl shadow-sm hover:bg-indigo-700 disabled:opacity-50 flex items-center space-x-2 transition-colors"
            >
              {loading && <Loader2 className="w-3.5 h-3.5 animate-spin" />}
              <span>Import Document</span>
            </button>
          </div>
        </form>

      </div>
    </div>
  );
}